-- The Supermarket Guide and its sponsorship (LOCKED by Sean 2026-11-01: "lock it, go with your defaults"). Concept session with V;
-- canon canon-ve-supermarket-guide, playbook ve-supermarket-guide. Records the decision; the build follows.
insert into public.knowledge_records (slug, title, category, subcategory, status, owner, always_load, load_priority, tags, version, created_by, updated_by, change_summary, body)
select 'canon-ve-supermarket-guide',
  'Vegans Explore: the Supermarket Guide, free while sponsored, and the supermarket and CPG sponsorship (LOCKED by Sean 2026-11-01)',
  'decisions', 'revenue', 'active', 'sar', false, 50,
  array['vegans-explore','guides','supermarkets','sponsorship','cpg','q1-2027'], 1, 'v', 'v',
  'Locked with V''s defaults (Sean: "lock it, go with your defaults").',
  jsonb_build_object(
    'why', 'Sean: "I want to run a campaign to have these markets sponsor us... we can bring their vegan items, their specials on vegan items... a doorway where the community will always know where to find these vegan items on the shelves." Then: "We get a sponsor, the guide is free, as long as the sponsorship is active... this is a CPG play as well... they''re buying their spot in this massive campaign that starts in Q1."',
    'guide', 'The Supermarket Guide, a Vegans Explore Guide on the Dairy Guide pattern: pick your store, see where the Vegan items are on its shelves, aisle by aisle, kept current by members; custom shopping lists; the produce section with what to buy and why; snack breakdowns; CPG products spotlighted with where to find them; each sponsor''s Vegan specials (also in the Daily Pulse).',
    'free_while_sponsored', 'Free to everyone while at least one supermarket sponsorship is active; that is the sponsor''s draw. With no sponsor it goes back to $11 or 1,100 points like every Guide.',
    'feeds', 'It feeds the rest of the site: each chain''s store page and store locator, the Daily Pulse, the ad rails and Markets > Supermarkets in the Directory.',
    'locations', 'One Directory listing per chain stays; each store is a row under it (address, pin, chapter), not its own listing. The chain''s page gets Find a store near you, and the chain''s chapters (listings.communities) come from its real store addresses. Each store carries its own aisle map, started from what the store gives us.',
    'fan_indexing', 'Members keep the aisle maps right the way the Stadium & Arena and Airport Guides work: confirm or update an item with a photo and a location check inside the store, points only once the team approves, first to confirm earns the bounty, later confirmations a little less.',
    'tiers', jsonb_build_array(
      'Title Sponsor, one at a time: $7,500 a quarter. "The Supermarket Guide, brought to you by ___" on the Guide, every ad, every festival card and booth, and the Daily Pulse; their stores featured first; their chain''s Supermarket Partner package included; first right to renew.',
      'Supermarket Partner, each chain: $1,500 a quarter, $750 for a chain in 3 chapters or fewer. Their store locator, store-by-store aisle maps indexed by members, their weekly Vegan specials in their chapters, ads on their store pages, a monthly report.',
      'Product Spotlight, CPG brands: $500 a quarter a product line. Featured in the Guide and its shopping lists, where to find it in partner stores, one ad rail spot; stacks on the $111 Brand Partner plan.',
      'Ads: ad slots on the Guide''s pages through the existing ad system, included in the tiers (the Title Sponsor the most); sold on their own later, once traffic data can price them.'),
    'terms', 'Quarterly, Q1 2027 first. Front Row Start: sign before January 1, 2027 and the rest of 2026 is promotion at no charge, the first charge in January for Q1. The first three Supermarket Partners keep their price through 2027 as Founding Partners.',
    'the_campaign', 'What every sponsor buys is a seat in the Q1 2027 campaign: paid ads pointing at the Guide, festivals and local events with QR cards, social and the Daily Pulse, and the build-up from the day they sign.',
    'the_2027_story', 'Every pitch says what Vegans Explore is gearing up to do in 2027, so being on the site means riding all of our promotion: expanding to new markets (chapters), growing our social media presence, partnerships with events, our growing Directory, the content creator network, and ongoing campaigns each quarter. Simply appearing on the site, a sponsor benefits from all of it. Stated as plans, never as reach already earned.',
    'honesty', 'Traffic is small today (221 real visitors in October 2026), so the pitch sells the campaign plan and the 2027 roadmap and reports real numbers; no promised reach or impressions we cannot show. Every sponsored spot is labeled Sponsored (FTC).',
    'first', 'Publix approached first for Title Sponsor (the anchor sponsor across our five Publix chapters, Florida first); Whole Foods and Sprouts next as Supermarket Partners.',
    'playbook', 've-supermarket-guide')
where not exists (select 1 from public.knowledge_records where slug = 'canon-ve-supermarket-guide');

insert into public.playbook_records (slug, brand_slug, author, body, source, kind)
select 've-supermarket-guide', 'vegans-explore', 'V',
  'Locked by Sean 2026-11-01 ("lock it, go with your defaults"). The Supermarket Guide: pick your store and find its Vegan items aisle by aisle (member-indexed, photo and in-store location check, approved before points, first-to-confirm bounties), custom shopping lists, the produce section, snack breakdowns, CPG spotlights with where to find them, and sponsors'' weekly Vegan specials (also in the Daily Pulse). Free while at least one supermarket sponsorship is active, else $11 or 1,100 points. Stores are rows under each chain''s one listing, with a store locator; chapters follow real store addresses. Sponsorship, quarterly from Q1 2027: Title Sponsor $7,500 (one at a time; brought to you by, featured stores, Partner package included, first right to renew); Supermarket Partner $1,500 ($750 for 3 chapters or fewer); Product Spotlight $500 a product line (stacks on the $111 Brand Partner plan); ad slots included, sold alone later. Front Row Start: sign before January 1, 2027, the rest of 2026 is promotion at no charge, first charge January; the first three Supermarket Partners keep their price through 2027. Every sponsor buys a seat in the Q1 2027 campaign (paid ads, festivals and local events with QR cards, social, the Daily Pulse) and hears the 2027 story: new chapters, a growing social presence, event partnerships, the growing Directory, the creator network, a campaign every quarter; being on the site means riding all of it. Plans are stated as plans; real numbers are reported; sponsored spots are labeled. First: Publix for Title, then Whole Foods and Sprouts. Canon canon-ve-supermarket-guide.',
  'text', 'decision'
where not exists (select 1 from public.playbook_records where slug = 've-supermarket-guide' and kind = 'decision');
